// The generated PkIconName constants (#111, step 6): one const per symbol in core/icons/icons.json, regenerated by the bootstrap.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { renderIconNames, iconMember, load } from '../generate-blazor.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const names = JSON.parse(fs.readFileSync(path.join(root, 'core', 'icons', 'icons.json'), 'utf8')).names;

test('the generator emits a constant for every name in icons.json, and the file on disk is current', () => {
    const text = load().files.get('PkIconName.cs');
    assert.ok(text, 'generate-blazor produced no PkIconName.cs');
    for (const n of names) assert.ok(text.includes(`public const string ${iconMember(n)} = "${n}";`), `no constant for icon "${n}"`);
    assert.equal((text.match(/public const string/g) ?? []).length, names.length);
    const onDisk = fs.readFileSync(path.join(root, 'blazor', 'src', 'PlainKit.Blazor', 'Generated', 'PkIconName.cs'), 'utf8').replace(/\r\n/g, '\n');
    assert.equal(onDisk, text, 'Generated/PkIconName.cs is stale: run node scripts/bootstrap.mjs');
});

test('member names: PascalCase, a leading digit gets a V, a collision is an error', () => {
    assert.equal(iconMember('arrow-left'), 'ArrowLeft');
    assert.equal(iconMember('3d-box'), 'V3dBox');
    assert.match(renderIconNames(['search']), /public const string Search = "search";/);
    assert.throws(() => renderIconNames(['a-b', 'a--b']), /both become/);
});
